import sys

import numpy as np
import wgpu

SHADER = """
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;

const W: i32 = {w};
const H: i32 = {h};

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {{
    let x = i32(id.x);
    let y = i32(id.y);
    if (x >= W || y >= H) {{
        return;
    }}
    var n: u32 = 0u;
    for (var dy = -1; dy <= 1; dy++) {{
        for (var dx = -1; dx <= 1; dx++) {{
            if (dx == 0 && dy == 0) {{
                continue;
            }}
            let nx = x + dx;
            let ny = y + dy;
            if (nx >= 0 && nx < W && ny >= 0 && ny < H) {{
                n += src[u32(ny * W + nx)];
            }}
        }}
    }}
    let i = u32(y * W + x);
    let alive = src[i] == 1u;
    dst[i] = select(select(0u, 1u, n == 3u), select(0u, 1u, n == 2u || n == 3u), alive);
}}
"""


def parse(path):
    with open(path) as f:
        tokens = f.read().split()
    w, h, gens = int(tokens[0]), int(tokens[1]), int(tokens[2])
    digits = "".join(tokens[3:])
    cells = np.frombuffer(digits[: w * h].encode(), dtype=np.uint8) - ord("0")
    return w, h, gens, cells.astype(np.uint32)


def run(w, h, gens, cells):
    if gens == 0:
        return cells
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    size = w * h * 4
    bufs = [device.create_buffer(size=size, usage=usage) for _ in range(2)]
    device.queue.write_buffer(bufs[0], 0, cells.tobytes())

    module = device.create_shader_module(code=SHADER.format(w=w, h=h))
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    groups = []
    for a, b in ((0, 1), (1, 0)):
        groups.append(
            device.create_bind_group(
                layout=pipeline.get_bind_group_layout(0),
                entries=[
                    {"binding": 0, "resource": {"buffer": bufs[a], "offset": 0, "size": size}},
                    {"binding": 1, "resource": {"buffer": bufs[b], "offset": 0, "size": size}},
                ],
            )
        )
    gx, gy = (w + 7) // 8, (h + 7) // 8
    encoder = device.create_command_encoder()
    cpass = encoder.begin_compute_pass()
    cpass.set_pipeline(pipeline)
    for g in range(gens):
        cpass.set_bind_group(0, groups[g % 2])
        cpass.dispatch_workgroups(gx, gy, 1)
    cpass.end()
    device.queue.submit([encoder.finish()])
    data = device.queue.read_buffer(bufs[gens % 2])
    return np.frombuffer(data, dtype=np.uint32)[: w * h].copy()


def main():
    w, h, gens, cells = parse(sys.argv[1])
    out = run(w, h, gens, cells).reshape(h, w)
    lines = [" ".join(str(int(v)) for v in row) for row in out]
    lines.append(f"ALIVE {int(out.sum())}")
    sys.stdout.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
